import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { basename, dirname, extname, join, relative, resolve, sep } from "node:path";
import { CONFIG_DIR_NAME } from "../config.ts";
import { parseFrontmatter } from "../utils/frontmatter.ts";
import { canonicalizePath, resolvePath } from "../utils/paths.ts";
import type { ResourceDiagnostic } from "./diagnostics.ts";
import { createSyntheticSourceInfo, type SourceInfo } from "./source-info.ts";
import { validateDescription, validateName } from "./skills.ts";

function toPosixPath(p: string): string {
	return p.split(sep).join("/");
}

export interface AgentFrontmatter {
	name?: string;
	description?: string;
	model?: string;
	skill?: string;
	tools?: string;
	systemPromptMode?: string;
	inheritProjectContext?: boolean;
	inheritSkills?: boolean;
	output?: string;
	defaultReads?: string;
	defaultContext?: string;
	[key: string]: unknown;
}

export interface AgentPersona {
	name: string;
	description: string;
	filePath: string;
	baseDir: string;
	sourceInfo: SourceInfo;
	frontmatter: AgentFrontmatter;
}

export interface LoadAgentsResult {
	agents: AgentPersona[];
	diagnostics: ResourceDiagnostic[];
}

export interface LoadAgentsFromDirOptions {
	dir: string;
	source: string;
}

function createAgentSourceInfo(filePath: string, baseDir: string, source: string): SourceInfo {
	switch (source) {
		case "user":
			return createSyntheticSourceInfo(filePath, {
				source: "local",
				scope: "user",
				baseDir,
			});
		case "project":
			return createSyntheticSourceInfo(filePath, {
				source: "local",
